from django.db import migrations


def backfill_licao_periodo(apps, schema_editor):
    """
    Popula o campo periodo nas Licoes existentes usando o PeriodoEBD
    que cobre a data da lição dentro do mesmo ano_letivo.
    Lições fora de qualquer período ficam com periodo=NULL (são legadas).
    """
    Licao = apps.get_model('escola_biblica', 'Licao')
    PeriodoEBD = apps.get_model('escola_biblica', 'PeriodoEBD')

    licoes_sem_periodo = Licao.objects.filter(periodo__isnull=True).select_related('turma__ano_letivo')

    for licao in licoes_sem_periodo:
        if licao.turma_id is None or licao.data is None:
            continue
        ano_letivo = licao.turma.ano_letivo
        periodo = PeriodoEBD.objects.filter(
            ano_letivo=ano_letivo,
            data_inicio__lte=licao.data,
            data_fim__gte=licao.data,
        ).first()
        if periodo is not None:
            licao.periodo = periodo
            licao.save(update_fields=['periodo'])


